(function(){
 let w = W(), h = H();
 function hexA(hex, a){
 const c = hex.replace('#','');
 const r = parseInt(c.substring(0,2),16);
 const g = parseInt(c.substring(2,4),16);
 const b = parseInt(c.substring(4,6),16);
 return 'rgba('+r+','+g+','+b+','+a+')';
 }
 const snowCount = 90;
 const snow = [];
 for(let i=0;i<snowCount;i++){
 snow.push({
 x: Math.random()*w,
 y: Math.random()*h,
 r: Math.random()*2.5+1.2,
 speed: Math.random()*0.4+0.15,
 phase: Math.random()*Math.PI*2,
 sway: Math.random()*0.6+0.2
 });
 }
 function resetSteam(){
 return {
 x: w*0.18 + Math.random()*w*0.22,
 y: h*0.78 + Math.random()*h*0.1,
 r: Math.random()*3+1.5,
 speed: Math.random()*0.35+0.15,
 age:0,
 maxLife: Math.random()*200+150,
 drift: Math.random()*0.4-0.2
 };
 }
 const steamCount = 36;
 const steam = [];
 for(let i=0;i<steamCount;i++){ steam.push(resetSteam()); }
 let t = 0;
 function drawTownSilhouette(){
 ctx.save();
 ctx.globalAlpha = 0.5;
 const baseY = h*0.72;
 ctx.fillStyle = hexA(PALETTE[2], 0.55);
 ctx.beginPath();
 ctx.moveTo(w*0.55, h);
 ctx.lineTo(w*0.55, baseY+40);
 ctx.lineTo(w*0.62, baseY);
 ctx.lineTo(w*0.68, baseY+30);
 ctx.lineTo(w*0.74, baseY-20);
 ctx.lineTo(w*0.8, baseY+25);
 ctx.lineTo(w*0.88, baseY-10);
 ctx.lineTo(w*0.95, baseY+30);
 ctx.lineTo(w, baseY+10);
 ctx.lineTo(w, h);
 ctx.closePath();
 ctx.fill();
 const lanternX = [w*0.68, w*0.85];
 lanternX.forEach(function(lx,i){
 const ly = baseY+10;
 const grad = ctx.createRadialGradient(lx,ly,1, lx,ly,26);
 grad.addColorStop(0, hexA(PALETTE[1], 0.5+0.15*Math.sin(t*0.8+i)));
 grad.addColorStop(1, hexA(PALETTE[1],0));
 ctx.fillStyle = grad;
 ctx.beginPath();
 ctx.arc(lx,ly,26,0,Math.PI*2);
 ctx.fill();
 });
 ctx.restore();
 }
 function drawCakeSlice(){
 const baseX = w*0.06, baseY = h*0.98;
 const topX = w*0.34, topY = h*0.56;
 const rightX = w*0.46, rightY = h*0.98;
 ctx.save();
 const glow = ctx.createRadialGradient(w*0.22,h*0.8,10, w*0.22,h*0.8, w*0.35);
 glow.addColorStop(0, hexA(PALETTE[0],0.35));
 glow.addColorStop(1, hexA(PALETTE[0],0));
 ctx.fillStyle = glow;
 ctx.beginPath();
 ctx.arc(w*0.22,h*0.8, w*0.35,0,Math.PI*2);
 ctx.fill();
 ctx.beginPath();
 ctx.moveTo(baseX, baseY);
 ctx.quadraticCurveTo(w*0.18, h*0.62, topX, topY);
 ctx.quadraticCurveTo(w*0.42, h*0.7, rightX, rightY);
 ctx.closePath();
 const cakeGrad = ctx.createLinearGradient(baseX, topY, rightX, baseY);
 cakeGrad.addColorStop(0, hexA(PALETTE[1],0.95));
 cakeGrad.addColorStop(0.5, hexA(PALETTE[0],0.9));
 cakeGrad.addColorStop(1, hexA(PALETTE[0],0.75));
 ctx.fillStyle = cakeGrad;
 ctx.fill();
 ctx.save();
 ctx.clip();
 const layerCount = 4;
 for(let i=1;i<layerCount;i++){
 const ly = baseY - (baseY-topY)*i/layerCount - Math.sin(t*0.5+i)*2;
 ctx.beginPath();
 ctx.moveTo(baseX - 20, ly);
 ctx.lineTo(rightX + 20, ly + 10);
 ctx.strokeStyle = hexA(PALETTE[1], 0.5);
 ctx.lineWidth = 6;
 ctx.stroke();
 }
 ctx.restore();
 ctx.beginPath();
 ctx.moveTo(baseX, baseY);
 ctx.quadraticCurveTo(w*0.18, h*0.62, topX, topY);
 ctx.strokeStyle = hexA('#ffffff', 0.55);
 ctx.lineWidth = 4;
 ctx.lineCap='round';
 ctx.stroke();
 ctx.restore();
 }
 function drawSteam(){
 steam.forEach(function(p){
 p.age++;
 p.y -= p.speed;
 p.x += p.drift*0.3;
 const lifeRatio = p.age/p.maxLife;
 const alpha = Math.sin(Math.PI*Math.min(lifeRatio,1))*0.35;
 ctx.beginPath();
 ctx.fillStyle = hexA(PALETTE[1], Math.max(alpha,0));
 ctx.arc(p.x, p.y, p.r*(1+lifeRatio), 0, Math.PI*2);
 ctx.fill();
 if(p.age > p.maxLife){ Object.assign(p, resetSteam()); }
 });
 }
 function drawSnow(){
 snow.forEach(function(s){
 s.y += s.speed;
 s.x += Math.sin(t*0.5+s.phase)*s.sway*0.2;
 if(s.y > h+10){ s.y = -10; s.x = Math.random()*w; }
 ctx.beginPath();
 ctx.fillStyle = hexA('#ffffff', 0.85);
 ctx.shadowColor = hexA('#ffffff',0.6);
 ctx.shadowBlur = 4;
 ctx.arc(s.x, s.y, s.r, 0, Math.PI*2);
 ctx.fill();
 ctx.shadowBlur = 0;
 });
 }
 function loop(){
 w = W(); h = H();
 ctx.clearRect(0,0,w,h);
 t += 0.016;
 drawTownSilhouette();
 drawCakeSlice();
 drawSteam();
 drawSnow();
 requestAnimationFrame(loop);
 }
 loop();
})();
